#!/usr/bin/env python3
"""Golden corpus and Unicode tables for BE_GO/internal/pydateutil.

Run through regen.sh with the oracle interpreter (CPython 3.13 with
python-dateutil 2.9.0.post0):

    gen_corpus.py tables <unicode_tables.go>
    gen_corpus.py corpus <corpus.jsonl.gz>

Every corpus line is one call of the real dateutil.parser.parse with an
injected default (the fake "now" at midnight) and a parserinfo whose century
pivot year is the fake now's year, in a process whose TZ is the line's "tz".
"""
