def ranges(predicate):
    out = []
    start = None
    for cp in range(0x110000):
        if 0xD800 <= cp <= 0xDFFF:
            hit = False
        else:
            hit = predicate(chr(cp))
        if hit and start is None:
            start = cp
        elif not hit and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, 0x10FFFF))
    return out


def write_tables(path):
    from dateutil.parser import parserinfo

    alpha = ranges(str.isalpha)
    digit = ranges(str.isdigit)
    space = ranges(str.isspace)
    zeros = []
    for lo, hi in ranges(str.isdecimal):
        if (hi - lo + 1) % 10:
            raise SystemExit("decimal run %x-%x is not a multiple of ten" % (lo, hi))
        for cp in range(lo, hi + 1):
            if unicodedata.decimal(chr(cp)) != (cp - lo) % 10:
                raise SystemExit("decimal digit %x breaks the run layout" % cp)
            if not chr(cp).isdigit():
                raise SystemExit("decimal %x is not a digit" % cp)
            if int(chr(cp)) != (cp - lo) % 10:
                raise SystemExit("int() disagrees for %x" % cp)
        zeros.extend(range(lo, hi + 1, 10))
    # The lookups lower() the token; the port matches ASCII tokens only. That
    # is exact while the only non-ASCII characters lowering to ASCII do not
    # occur in any keyword.
    lowers = [cp for cp in range(128, 0x110000) if not 0xD800 <= cp <= 0xDFFF and chr(cp).lower().isascii()]
    if lowers != [0x212A]:
        raise SystemExit("unexpected non-ASCII characters lowering to ASCII: %r" % lowers)
    info = parserinfo()
    words = set()
    for table in (info._jump, info._weekdays, info._months, info._hms, info._ampm, info._utczone, info._pertain):
        words.update(table)
    if any("k" in w for w in words):
        raise SystemExit("a keyword contains 'k'; KELVIN SIGN must be handled")

    def table(name, rows, comment):
        lines = ["// %s" % comment, "var %s = [][2]rune{" % name]
        for lo, hi in rows:
            lines.append("\t{0x%X, 0x%X}," % (lo, hi))
        lines.append("}")
        return "\n".join(lines)

    parts = [
        "// Code generated by testdata/gen_corpus.py tables; DO NOT EDIT.",
        "",
        "package pydateutil",
        "",
        "// unicodeVersion is unicodedata.unidata_version of the oracle interpreter.",
        'const unicodeVersion = "%s"' % unicodedata.unidata_version,
        "",
        table("alphaRanges", alpha, "alphaRanges are the inclusive ranges where str.isalpha() is true."),
        "",
        table("digitRanges", digit, "digitRanges are the inclusive ranges where str.isdigit() is true."),
        "",
        table("spaceRanges", space, "spaceRanges are the inclusive ranges where str.isspace() is true."),
        "",
        "// decimalZeros are the zero digits of every run of ten decimal digits",
        "// (str.isdecimal(); the characters int() and Decimal() accept).",
        "var decimalZeros = []rune{",
    ]
    parts.extend("\t0x%X," % z for z in zeros)
    parts.append("}")
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(parts) + "\n")


